/* Compute the inverse Fourier transform of x in‑place.
   The forward FFT (fft) is assumed to compute the DFT without any scaling
   (i.e. X[k] = Σ x[n]·exp(‑j·2π·k·n/N)).  The inverse is obtained by

       x = (1/N) * conj( fft( conj( x ) ) )

   All element‑wise operations are parallelised with HPX. */
void ifft(std::vector<std::complex<double>>& x)
{
    const std::size_t n = x.size();
    using namespace hpx::parallel;

    // 1. conjugate the input
    for_each(execution::par, x.begin(), x.end(),
        [](std::complex<double>& v) { v = std::conj(v); });

    // 2. forward FFT (assumed to be parallel inside its implementation)
    fft(x);

    // 3. conjugate the result of the FFT
    for_each(execution::par, x.begin(), x.end(),
        [](std::complex<double>& v) { v = std::conj(v); });

    // 4. scale by 1/N to obtain the normalized inverse transform
    const double scale = 1.0 / static_cast<double>(n);
    for_each(execution::par, x.begin(), x.end(),
        [scale](std::complex<double>& v) { v *= scale; });
}
