/* forward declaration – assumes an in‑place Cooley‑Tukey FFT */
void fft(std::vector<std::complex<double>> &x);

/* In‑place inverse Fourier transform using HPX for the element‑wise
 * conjugate and scaling steps.  The forward FFT is reused, so the
 * whole transform runs in O(N log N) time with N = x.size().
 *
 * The algorithm:
 *   1. x ← conj(x)                (parallel)
 *   2. fft(x)                     (forward transform)
 *   3. x ← conj(x) / N            (parallel)
 *
 * This is mathematically equivalent to the inverse FFT. */
void ifft(std::vector<std::complex<double>> &x)
{
    const std::size_t n = x.size();

    // ------------------------------------------------------------------
    // Step 1: conjugate the input (parallel)
    // ------------------------------------------------------------------
    hpx::for_loop(hpx::execution::par, static_cast<std::size_t>(0), n,
        [&x](std::size_t i) {
            x[i] = std::conj(x[i]);
        });

    // ------------------------------------------------------------------
    // Step 2: forward FFT (assumed already parallelised internally)
    // ------------------------------------------------------------------
    fft(x);

    // ------------------------------------------------------------------
    // Step 3: conjugate again and scale by 1/N (parallel)
    // ------------------------------------------------------------------
    const double inv_n = 1.0 / static_cast<double>(n);
    hpx::for_loop(hpx::execution::par, static_cast<std::size_t>(0), n,
        [&x, inv_n](std::size_t i) {
            x[i] = std::conj(x[i]) * inv_n;
        });
}
